window.PAIRS=[{"n":1,"s":0.61,"o":{"i":"세무사2022_59-46-4","t":"취소소송에서의 피고적격에 관한 규정은 무효등 확인소송의 경우에 준용한다.","y":2022,"e":"세무사 1차"},"x":{"i":"세무사2022_59-46-5","t":"취소소송에서의 행정심판과의 관계에 관한 규정은 무효등 확인소송의 경우에 준용한다.","y":2022,"e":"세무사 1차"}},{"n":8,"s":0.725,"o":{"i":"세무사2025_62-68-3","t":"과세처분의 취소소송에서 청구가 기각된 확정판결의 기판력은 그 과세처분의 무효 확인을 구하는 소송에도 미친다.","y":2025,"e":"세무사 1차"},"x":{"i":"세무사2024_61-48-5","t":"과세처분의 취소소송에서 청구가 기각된 확정판결의 기판력은 그 과세처분의 무효확인을 구하는 소송에는 미치지 아니한다.","y":2024,"e":"세무사 1차"}},{"n":8,"s":0.591,"o":{"i":"세무사2021_58-74-3","t":"거부처분 후에 법령이 개정ㆍ시행된 경우에는 개정된 법령을 새로운 사유로 들어 다시 이전의 신청에 대한 거부처분을 할 수 있다.","y":2021,"e":"세무사 1차"},"x":{"i":"세무사2026_63-68-5","t":"거부처분취소판결이 확정된 후 법령이 개정ㆍ시행된 경우에도 개정된 법령을 새로운 사유로 들어 다시 이전의 신청에 대한 거부처분을 할 수 없다.","y":2026,"e":"세무사 1차"}},{"n":8,"s":0.55,"o":{"i":"세무사2025_62-69-5","t":"간접강제결정에 기한 배상금은 확정판결의 취지에 따른 재처분의 지연에 대한 제재나 손해배상이 아니라 재처분의 이행에 관한 심리적 강제수단이다.","y":2025,"e":"세무사 1차"},"x":{"i":"세무사2026_63-59-2","t":"간접강제결정에 기한 배상금은 확정판결의 취지에 따른 재처분의 지연에 대한 제재이다.","y":2026,"e":"세무사 1차"}},{"n":8,"s":0.529,"o":{"i":"세무사2021_58-75-5","t":"제3자에 의한 재심청구는 확정판결이 있음을 안 날로부터 30일 이내, 판결이 확정된 날로부터 1년 이내에 제기하여야 한다.","y":2021,"e":"세무사 1차"},"x":{"i":"세무사2024_61-59-2","t":"재심청구는 확정판결이 있음을 안 날로부터 90일 이내에 제기하여야 한다.","y":2024,"e":"세무사 1차"}},{"n":9,"s":0.7,"o":{"i":"세무사2016_53-47-1","t":"유효확인소송은 무효등확인소송에 포함된다.","y":2016,"e":"세무사 1차"},"x":{"i":"세무사2016_53-47-4","t":"작위의무확인소송은 무효등확인소송에 포함된다.","y":2016,"e":"세무사 1차"}},{"n":9,"s":0.692,"o":{"i":"세무사2026_63-76-3","t":"법원이 위법성 여부를 판단하는 기준시점은 판결시이다.","y":2026,"e":"세무사 1차"},"x":{"i":"세무사2017_54-60-3","t":"법원이 위법성 여부를 판단하는 기준시점은 처분시이다.","y":2017,"e":"세무사 1차"}},{"n":9,"s":0.452,"o":{"i":"세무사2021_58-44-3","t":"부작위위법확인소송은 처분의 신청을 한 자로서 부작위의 위법의 확인을 구할 법률상 이익이 있는 자만이 제기할 수 있다.","y":2021,"e":"세무사 1차"},"x":{"i":"세무사2016_53-65-3","t":"부작위위법의 확인을 구할 법률상 이익이 있는 자는 신청을 하지 않았더라도 부작위위법확인소송을 제기할 수 있다.","y":2016,"e":"세무사 1차"}},{"n":9,"s":0.44,"o":{"i":"세무사2023_60-75-3","t":"당사자의 신청에 대한 행정청의 거부처분이 있는 경우에는 부작위위법확인소송은 허용되지 않는다.","y":2023,"e":"세무사 1차"},"x":{"i":"세무사2025_62-73-2","t":"당사자의 신청에 대한 행정청의 거부처분은 부작위위법확인소송의 대상이 된다.","y":2025,"e":"세무사 1차"}},{"n":7,"s":0.833,"o":{"i":"세무사2023_60-59-4","t":"정보공개거부처분 취소소송에서 비공개사유의 주장·입증책임은 피고에게 있다.","y":2023,"e":"세무사 1차"},"x":{"i":"세무사2017_54-77-4","t":"정보공개거부처분 취소소송에서 비공개사유의 주장·입증책임은 원고에게 있다.","y":2017,"e":"세무사 1차"}},{"n":7,"s":0.659,"o":{"i":"세무사2023_60-59-1","t":"항고소송에 있어서 원고는 전심절차에서 주장하지 아니한 공격방어방법을 소송절차에서 주장할 수 있다.","y":2023,"e":"세무사 1차"},"x":{"i":"세무사2024_61-44-3","t":"원고는 전심절차에서 주장하지 아니한 공격방어방법을 소송절차에서 주장할 수 없다.","y":2024,"e":"세무사 1차"}},{"n":7,"s":0.529,"o":{"i":"세무사2022_59-69-5","t":"처분사유의 추가ㆍ변경은 사실심 변론종결시까지만 허용된다.","y":2022,"e":"세무사 1차"},"x":{"i":"세무사2025_62-64-4","t":"행정청의 처분사유의 추가ㆍ변경은 사실심 개시전까지만 허용된다.","y":2025,"e":"세무사 1차"}},{"n":7,"s":0.479,"o":{"i":"세무사2021_58-71-5","t":"법원은 2021. 12. 3.까지 제출된 모든 자료를 종합하여 2021. 5. 24. 당시 존재하였던 객관적 사실을 확정하고 그 사실에 기초하여 처분의 위법 여부를 판단할 수 있다.","y":2021,"e":"세무사 1차"},"x":{"i":"세무사2021_58-71-4","t":"법원은 2021. 5. 24. 당시 존재하였던 자료나 행정청에 제출되었던 자료만으로 2021. 5. 24. 당시 존재하였던 객관적 사실을 확정하고 그 사실에 기초하여 처분의 위법 여부를 판단하여야 한다.","y":2021,"e":"세무사 1차"}},{"n":10,"s":0.855,"o":{"i":"세무사2021_58-42-1","t":"민중소송은 국가 또는 공공단체의 기관이 법률에 위반되는 행위를 한 때에 직접 자기의 법률상 이익과 관계없이 그 시정을 구하기 위하여 제기하는 소송이다.","y":2021,"e":"세무사 1차"},"x":{"i":"세무사2022_59-43-4","t":"공공단체의 기관이 법률에 위반되는 행위를 한 때에 직접 자기의 법률상 이익과 관계없이 그 시정을 구하기 위하여 제기하는 소송이다.","y":2022,"e":"세무사 1차"}},{"n":10,"s":0.429,"o":{"i":"세무사2022_59-47-2","t":"민중소송으로써 처분등의 취소를 구하는 소송에는 그 성질에 반하지 아니하는 한 취소소송에 관한 규정을 준용한다.","y":2022,"e":"세무사 1차"},"x":{"i":"세무사2016_53-75-4","t":"민중소송에는 그 성질에 반하지 아니하는 한 취소소송에 관한 규정을 준용하지만, 기관소송의 경우에는 그러하지 아니하다.","y":2016,"e":"세무사 1차"}},{"n":10,"s":0.415,"o":{"i":"세무사2026_63-77-5","t":"「헌법재판소법」에 의하여 헌법재판소의 관장사항으로 되는 소송은 제외한다.","y":2026,"e":"세무사 1차"},"x":{"i":"세무사2016_53-75-5","t":"기관소송은 헌법재판소법상 헌법재판소의 관장사항으로 되는 소송을 포함한다.","y":2016,"e":"세무사 1차"}},{"n":10,"s":0.405,"o":{"i":"세무사2023_60-68-4","t":"제3자에 의한 재심청구 규정은 당사자소송에 준용되지 않는다.","y":2023,"e":"세무사 1차"},"x":{"i":"세무사2026_63-73-3","t":"취소소송의 소송비용에 관한 규정은 당사자소송에 준용되지 않는다.","y":2026,"e":"세무사 1차"}},{"n":4,"s":0.824,"o":{"i":"세무사2017_54-79-2","t":"취소소송의 제1심 관할법원은 피고의 소재지를 관할하는 행정법원으로 한다.","y":2017,"e":"세무사 1차"},"x":{"i":"세무사2022_59-50-3","t":"취소소송의 제1심관할법원은 원고의 소재지를 관할하는 행정법원으로 한다.","y":2022,"e":"세무사 1차"}},{"n":4,"s":0.77,"o":{"i":"세무사2022_59-50-1","t":"국가의 사무를 위탁받은 공공단체를 피고로 하여 취소소송을 제기하는 경우 대법원소재지를 관할하는 행정법원에 제기할 수 있다.","y":2022,"e":"세무사 1차"},"x":{"i":"세무사2021_58-56-4","t":"국가의 사무를 위탁받은 공공단체를 피고로 하여 취소소송을 제기하는 경우 대법원소재지를 관할하는 행정법원에 제기하는 것은 관할 위반이다.","y":2021,"e":"세무사 1차"}},{"n":4,"s":0.577,"o":{"i":"세무사2017_54-64-4","t":"취소소송에 부당이득반환청구가 병합된 경우에 부당이득반환청구가 인용되려면 취소판결이 확정되어야 하는 것은 아니다.","y":2017,"e":"세무사 1차"},"x":{"i":"세무사2023_60-45-1","t":"취소소송에 부당이득반환청구소송이 병합된 경우 부당이득반환청구가 인용되려면 취소판결이 확정되어야 한다.","y":2023,"e":"세무사 1차"}},{"n":4,"s":0.512,"o":{"i":"세무사2024_61-63-5","t":"피고경정의 결정이 있은 때에는 종전의 피고에 대한 소송은 취하된 것으로 본다.","y":2024,"e":"세무사 1차"},"x":{"i":"세무사2022_59-78-2","t":"피고경정의 허가가 있는 때에는 종전의 피고에 대한 소송은 각하된 것으로 본다.","y":2022,"e":"세무사 1차"}},{"n":2,"s":0.78,"o":{"i":"세무사2021_58-66-4","t":"사립학교 교원 징계에 대한 교원소청심사위원회의 결정은 행정심판의 재결에 해당하지 않는다.","y":2021,"e":"세무사 1차"},"x":{"i":"세무사2026_63-55-4","t":"사립학교 교원징계에 대한 교원소청심사위원회의 결정은 행정심판의 재결에 해당한다.","y":2026,"e":"세무사 1차"}},{"n":2,"s":0.76,"o":{"i":"세무사2022_59-49-5","t":"행정행위의 부관 중 부담은 항고소송의 대상이 될 수 있다.","y":2022,"e":"세무사 1차"},"x":{"i":"세무사2016_53-59-3","t":"행정행위의 부관 중 부담은 항고소송의 대상이 될 수 없다.","y":2016,"e":"세무사 1차"}},{"n":5,"s":0.618,"o":{"i":"세무사2022_59-53-2","t":"조세심판에서의 재결청의 재조사결정에 따른 행정소송의 제소기간의 기산점은 후속 처분의 통지를 받은 날이다.","y":2022,"e":"세무사 1차"},"x":{"i":"세무사2026_63-52-3","t":"재결청의 재조사결정에 따른 행정소송의 제소기간의 기산점은 이의신청의 대상인 처분의 통지를 받은 날이다.","y":2026,"e":"세무사 1차"}},{"n":5,"s":0.567,"o":{"i":"세무사2026_63-52-5","t":"취소소송의 제소기간의 규정은 당사자소송에 준용되지 않는다.","y":2026,"e":"세무사 1차"},"x":{"i":"세무사2016_53-63-4","t":"취소소송의 제소기간의 규정은 당사자소송에 적용된다.","y":2016,"e":"세무사 1차"}},{"n":5,"s":0.524,"o":{"i":"세무사2023_60-78-2","t":"고시에 의해 불특정 다수인에게 행정처분을 하는 경우에는 그 행정처분에 이해관계를 갖는 자는 고시가 있었다는 사실을 현실적으로 알았는지 여부에 관계없이 고시가 효력을 발생하는 날에 행정처분이 있음을 알았다고 보아야 한다.","y":2023,"e":"세무사 1차"},"x":{"i":"세무사2022_59-53-4","t":"고시에 의하여 불특정다수인을 대상으로 행정처분을 하는 경우, 그 행정처분에 이해관계를 갖는 자는 고시가 있었다는 사실을 현실적으로 안 날에 행정처분이 있음을 알았다고 보아야 한다.","y":2022,"e":"세무사 1차"}},{"n":5,"s":0.511,"o":{"i":"세무사2017_54-67-3","t":"특정인에 대한 행정처분을 주소불명 등의 이유로 송달할 수 없어 관보 등에 공고한 경우에는 상대방이 당해 처분이 있었다는 사실을 현실적으로 안 날에 그 처분이 있음을 알았다고 보아야 한다.","y":2017,"e":"세무사 1차"},"x":{"i":"세무사2023_60-78-1","t":"특정인에 대한 행정처분을 주소불명 등의 이유로 송달할 수 없어 관보에 공고한 경우에는, 공고가 효력을 발생하는 날에 상대방이 그 행정처분이 있음을 알았다고 보아야한다.","y":2023,"e":"세무사 1차"}},{"n":6,"s":0.818,"o":{"i":"세무사2017_54-58-2","t":"집행정지의 결정에 대한 즉시항고에는 결정의 집행을 정지하는 효력이 없다.","y":2017,"e":"세무사 1차"},"x":{"i":"세무사2016_53-73-2","t":"집행정지의 결정에 대한 즉시항고에는 결정의 집행을 정지하는 효력이 있다.","y":2016,"e":"세무사 1차"}},{"n":6,"s":0.302,"o":{"i":"세무사2022_59-60-5","t":"신청인의 본안청구가 이유 없음이 명백할 때에는 집행정지를 명할 수 없다.","y":2022,"e":"세무사 1차"},"x":{"i":"세무사2025_62-53-5","t":"신청인의 본안청구가 이유 없음이 명백하지 않아야 한다는 것은 집행정지의 요건에 포함되지 않는다.","y":2025,"e":"세무사 1차"}}];
